    TranslatedDialog("New tracks", "dialogs/new_tracks.rs", command = "track.new") { onRun, onDismiss -> NewTracksDialog(onRun, onDismiss) },
    TranslatedDialog("Ops windows tempo ops", "dialogs/ops_windows.rs", command = "event.tempo_ops_window") { onRun, onDismiss -> OpsWindowsTempoOpsDialog(onRun, onDismiss) },
